text(await tools.exec_command({cmd:"cat >> tests/periods.spec.ts <<'EOF'

for (const kind of ["member", "funder"] as const) {
  test(`${kind} retains identity and the loaded view during delayed tab navigation`, async ({ page, backend }) => {
    const canonicalPath = kind === "member" ? "/members/1" : `/funders/${funderId}`;
    const initialPath = kind === "member" ? canonicalPath : "/funders/99999999-9999-4999-8999-999999999999";
    const response = Promise.withResolvers<void>();
    await backend.route("**/api/*", async (route) => {
      const period = new URL(route.request().url()).searchParams.get("period");
      if (period === "historical") await response.promise;
      await route.fulfill({ json: kind === "member"
        ? { ...memberDetails, period }
        : { ...funderDetails, period, entry_count: period === "historical" ? 41 : 1 } });
    });
    await page.goto(`${initialPath}?period=current-year`);
    const identity = page.locator(".member-identity");
    const header = await identity.elementHandle();
    const text = await identity.innerText();
    const bounds = await identity.boundingBox();
    const historyName = kind === "member" ? "Declaration history" : "Funding history";
    const nav = page.getByRole("navigation", { name: `${kind === "member" ? "Member" : "Funder"} views` });
    if (kind === "funder") {
      await expect(identity).not.toContainText("funding entry");
      await expect(page.getByRole("region", { name: "Summary", exact: true }).getByText("1 funding entry", { exact: true })).toBeVisible();
    }
    await nav.getByRole("link", { name: historyName, exact: true }).click();
    try {
      await expect(page.locator("#details")).toHaveAttribute("aria-busy", "true");
      expect(await header!.evaluate((node) => node.isConnected)).toBe(true);
      await expect(nav.getByRole("link", { name: "Summary", exact: true })).toHaveAttribute("aria-current", "page");
      await expect(page.getByRole("region", { name: "Summary", exact: true })).toBeVisible();
      await expect(identity).toHaveText(text);
    } finally { response.resolve(); }
    await expect(page).toHaveURL(`${canonicalPath}/history?period=current-year`);
    await expect(nav.getByRole("link", { name: historyName, exact: true })).toHaveAttribute("aria-current", "page");
    expect(await header!.evaluate((node) => node.isConnected)).toBe(true);
    expect(await identity.innerText()).toBe(text);
    expect(await identity.boundingBox()).toEqual(bounds);
    await expect(page.getByRole("region", { name: "Summary", exact: true })).toHaveCount(0);
    if (kind === "funder") {
      await expect(page.getByRole("region", { name: "Funding history", exact: true }).getByText("41 funding entries", { exact: true })).toBeVisible();
      await page.getByLabel("Registered from").fill("2099-01-01");
      await page.getByLabel("Registered from").dispatchEvent("change");
      await expect(page.getByText("41 funding entries", { exact: true })).toBeVisible();
    }
    await nav.getByRole("link", { name: "Summary", exact: true }).click();
    await expect(page).toHaveURL(`${canonicalPath}?period=current-year`);
    await expect(page.getByRole("navigation", { name: "Reporting period" }).getByRole("link", { name: "This year", exact: true })).toHaveAttribute("aria-current", "page");
    expect(await identity.boundingBox()).toEqual(bounds);
    await header!.dispose();
  });
}
EOF
